def solve(inputs: dict) -> float:
    rems = inputs['remainders']
    mods = inputs['moduli']

    def extended_gcd(a, b):
        if a == 0:
            return b, 0, 1
        gcd, x1, y1 = extended_gcd(b % a, a)
        x = y1 - (b // a) * x1
        y = x1
        return gcd, x, y

    def mod_inverse(a, m):
        gcd, x, _ = extended_gcd(a, m)
        if gcd != 1:
            return None
        return (x % m + m) % m

    def crt(remainders, moduli):
        x = 0
        M = 1
        for m in moduli:
            M *= m

        for i in range(len(remainders)):
            Mi = M // moduli[i]
            yi = mod_inverse(Mi, moduli[i])
            x += remainders[i] * Mi * yi

        return x % M

    result = crt(rems, mods)
    return float(result)

