def solve(inputs: dict) -> float:
    M = inputs['matrix']
    n = inputs['exponent']
    mod = inputs['modulus']

    def matrix_mult(A, B, modulus):
        """Multiply two 2x2 matrices mod modulus"""
        result = [[0, 0], [0, 0]]
        for i in range(2):
            for j in range(2):
                for k in range(2):
                    result[i][j] = (result[i][j] + A[i][k] * B[k][j]) % modulus
        return result

    def matrix_power(mat, exp, modulus):
        """Compute mat^exp mod modulus using binary exponentiation"""
        result = [[1, 0], [0, 1]]  # Identity matrix
        base = [row[:] for row in mat]  # Copy matrix

        while exp > 0:
            if exp % 2 == 1:
                result = matrix_mult(result, base, modulus)
            base = matrix_mult(base, base, modulus)
            exp //= 2

        return result

    result_matrix = matrix_power(M, n, mod)

    # Sum all entries
    total = sum(result_matrix[i][j] for i in range(2) for j in range(2))

    return float(total % mod)

